// Shortens Square's customer records to what the owner needs.
const customers = $input.first().json.customers ?? [];
return [{
  json: {
    found: customers.length,
    customers: customers.slice(0, 5).map((c) => ({
      name: [c.given_name, c.family_name].filter(Boolean).join(' ') || c.company_name || null,
      email: c.email_address ?? null,
      phone: c.phone_number ?? null,
      customer_since: c.created_at?.slice(0, 10) ?? null,
    })),
  },
}];
